function loadDailyContent() {
  var dayOfEpoch = Math.floor(Date.now() / (1000 * 60 * 60 * 24));

  // تحميل الآية
  var ayahIndex = dayOfEpoch % dailyAyahs.length;
  var selectedAyah = dailyAyahs[ayahIndex];
  var ayahTextEl = document.getElementById('daily-ayah-text');
  var ayahSourceEl = document.getElementById('daily-ayah-source');
  if (ayahTextEl && ayahSourceEl) {
    ayahTextEl.innerText = selectedAyah.text;
    ayahSourceEl.innerText = "\u0633\u0648\u0631\u0629 ".concat(selectedAyah.surah, " - \u0627\u0644\u0622\u064A\u0629 ").concat(selectedAyah.number);
  }

  // تحميل الحديث
  var hadithIndex = dayOfEpoch % dailyAhadith.length;
  var selectedHadith = dailyAhadith[hadithIndex];
  var hadithTextEl = document.getElementById('daily-hadith-text');
  var hadithSourceEl = document.getElementById('daily-hadith-source');
  if (hadithTextEl && hadithSourceEl) {
    hadithTextEl.innerText = selectedHadith.text;
    hadithSourceEl.innerText = selectedHadith.source;
  }
}
